def chains(n):
    total = 0
    for odd in range(1, n + 1, 2):
        k = 0; v = odd
        while v <= n: k += 1; v *= 2
        total += (k + 1) // 2
    return total
def slow(n): return max(bin(m).count("1") for m in range(1 << n) if not any(m >> i & 1 and 2 * (i + 1) <= n and m >> (2 * i + 1) & 1 for i in range(n)))
assert all(chains(n) == slow(n) for n in range(1, 15))
result = chains(30)
